                    { 107, "Common", "health_center", "4.1 / 6.2", 27, "الخطة الاستراتيجية", "المواءمة مع استراتيجية الجامعة ← الخطة التنفيذية السنوية ← رصد نسبة الإنجاز : التحقق من ارتباط خطة المركز الصحي بالخطة الاستراتيجية للجامعة وتحويلها لأنشطة سنوية متابعة دورياً." },
                    { 108, "Common", "health_center", "9.1.1", 28, "مؤشرات الأداء", "بطاقة تعريف المؤشر ← جمع البيانات والقياس ← المقارنة بالمستهدف ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للمركز الصحي وتحليل الفجوات بين المستهدف والمتحقق." },
                    { 109, "Common", "health_center", "4.1", 29, "تحليل SWOT", "رصد العوامل الداخلية والخارجية ← المناقشة والإقرار ← الربط بالمخاطر والفرص : التحقق من إجراء تحليل علمي لنقاط القوة والضعف والفرص والتهديدات الخاصة بالمركز الصحي وتحديثه." },
                    { 110, "Common", "health_center", "6.1", 30, "خطة الفرص", "استخلاص الفرصة من SWOT ← وضع خطة استثمارها ← التنفيذ وقياس الأثر : التحقق من تحويل الفرص المتاحة للمركز إلى مبادرات تطويرية مجدولة ومتابعة تنفيذها." },
                    { 111, "Common", "health_center", "6.1", 31, "إدارة المخاطر", "تحديد الخطر ← تقييم (الاحتمالية × الأثر) ← إجراء التحكم والوقاية ← إعادة التقييم : التحقق من حصر المخاطر الطبية والتشغيلية وتقييمها وتطبيق إجراءات السيطرة عليها ومتابعتها." },
                    { 112, "Common", "health_center", "7.2", 32, "التدريب والكفاءة", "تحديد الفجوة التدريبية ← خطة التدريب ← التنفيذ ← تقييم فاعلية التدريب : التحقق من كفاءة الكادر الطبي والتمريضي وتحديد احتياجاتهم التدريبية وإشراكهم في دورات تخصصية وقياس أثرها." },
                    { 113, "DepartmentSpecific", "health_center", "8.5.1", 33, "إجراءات العلاج", "استقبال المراجع ← الفرز الأولي (العلامات الحيوية) ← التشخيص الطبي ← صرف العلاج والتوثيق : التحقق من وجود مسار عمل موثق ومنظم لاستقبال ومعاينة وعلاج المراجعين وتوثيق كل حالة في السجل الطبي." },
                    { 114, "DepartmentSpecific", "health_center", "8.5.1", 34, "إدارة الحالات الطارئة", "الجاهزية المسبقة ← الاستجابة والإسعاف الفوري ← التحويل للمستشفى ← التوثيق والمتابعة : التحقق من جاهزية غرفة الطوارئ وسيارة الإسعاف على مدار الدوام، وتوثيق الحالات الطارئة وإجراءات تحويلها للمستشفيات." },
                    { 115, "DepartmentSpecific", "health_center", "8.5.1", 35, "حملات التوعية", "خطة التوعية الصحية ← الإعداد والإعلان ← التنفيذ (حملات/ندوات/نشرات) ← التقييم : التحقق من تخطيط وتنفيذ المركز لحملات توعية وتثقيف صحي وأيام طبية لطلبة وموظفي الجامعة." },
                    { 116, "DepartmentSpecific", "health_center", "7.1.4 / 8.5.1", 36, "مكافحة العدوى", "بروتوكول التعقيم ← التطبيق اليومي ← الفحص والمراقبة ← التوثيق : التحقق من التزام المركز ببروتوكولات التعقيم الصارمة للأدوات الطبية والأسطح والعيادات ومعدات الوقاية الشخصية (PPE)." },
                    { 117, "DepartmentSpecific", "health_center", "7.1.4 / 8.5.1", 37, "إدارة النفايات الطبية", "الفرز في المصدر (أكياس/حاويات مخصصة) ← الجمع والتخزين الآمن المؤقت ← التسليم لجهة مرخصة للإتلاف : التحقق من فصل النفايات الطبية الحادة والخطرة عن النفايات العادية والتخلص الآمن منها عبر جهة مرخصة رسمياً." },
                    { 118, "DepartmentSpecific", "health_center", "8.5.4", 38, "توفر الأدوية", "تحديد القائمة الأساسية ← الطلب والتوريد ← التخزين الآمن ومراقبة الحرارة والصلاحية ← الجرد والصرف : التحقق من توفر الأدوية الأساسية وأدوية الطوارئ، وسلامة تخزينها، ومراقبة تواريخ انتهائها، وضبط صرفها بموجب وصفات." },
                    { 119, "DepartmentSpecific", "health_center", "7.1.5", 39, "صيانة الأجهزة الطبية ومعايرتها", "حصر الأجهزة ← خطة الصيانة الوقائية والمعايرة ← الفحص وإصدار الشهادة ← إصلاح الأعطال : التحقق من خضوع كافة الأجهزة الطبية لصيانة دورية ومعايرة فنية تضمن دقة القراءات وسلامة الاستخدام." },
                    { 120, "Common", "health_center", "9.1.2 / 10.2", 40, "الشكاوى الصحية", "استقبال الشكوى ← التوثيق والتصنيف ← التحقيق والمعالجة ← الإجراء التصحيحي وإبلاغ المشتكي : التحقق من وجود قناة فعالة لتلقي شكاوى المراجعين حول الخدمات الصحية ومعالجتها جذرياً لمنع تكرارها." },
                    { 121, "Common", "health_center", "9.1.2", 41, "استبانات رضا الطلبة وتحليلها", "توزيع الاستبانة ← جمع البيانات والتحليل الإحصائي ← استخراج فرص التحسين ← تنفيذ خطة التحسين : التحقق من قياس رضا الطلبة الدوري عن خدمات المركز الصحي وتحويل النتائج إلى إجراءات تطويرية موثقة." },
                    { 202, "Common", "admission", "5.2 / 8.2.2", 44, "السياسة التعليمية", "الصياغة والاعتماد ← التوافق مع أنظمة التعليم العالي ← الإعلان للطلبة والمعيّنين : التحقق من وجود سياسة وتعليمات قبول وتسجيل ومنح درجات علمية معتمدة ومتوافقة مع سياسة الجامعة التعليمية ومعلنة للطلبة." },
                    { 203, "Common", "admission", "7.1.4 / 8.5.3", 45, "بيئة العمل (السلامة العامة وخدمات ذوي الاحتياجات)", "تهيئة صالات استقبال الطلبة ← متطلبات السلامة ← نوافذ وتسهيلات ذوي الإعاقة : التحقق من ملاءمة بيئة العمل وصالات انتظار ومراجعة الطلبة، وتوفير شروط السلامة العامة وتسهيلات خدمة الطلبة ذوي الاحتياجات الخاصة." },
                    { 204, "Common", "admission", "7.5.2 / 7.5.3", 46, "ضبط الوثائق والسجلات وحفظها", "الترميز والاعتماد ← استخدام النسخ السارية ← الفهرسة والحفظ الآمن ← مدة الحفظ : التحقق من ضبط كافة الوثائق المرجعية والسجلات الأكاديمية وفق نظام إدارة الجودة وحمايتها من التلف أو الفقدان." },
                    { 205, "Common", "admission", "7.5.3 / 8.5.5", 47, "حماية البيانات", "صلاحيات الدخول (Role-Based) ← التشفير والسرية ← توثيق التعديلات (Audit Log) ← النسخ الاحتياطي : التحقق من حماية سرية وأمن البيانات الأكاديمية والشخصية للطلبة والعلامات، وضبط صلاحيات الدخول والتعديل على نظام التسجيل." },
                    { 206, "Common", "admission", "7.2", 48, "التدريب والكفاءة", "حصر الاحتياج التدريبي ← خطة التدريب ← التنفيذ ← قياس أثر التدريب : التحقق من تأهيل وتدريب كادر القبول والتسجيل على الأنظمة الإلكترونية، التشريعات الأكاديمية، خدمة الطلبة، وتقييم أثر التدريب." },
                    { 207, "Common", "admission", "6.2", 49, "هدف الجودة", "صياغة أهداف ذكية ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس للدائرة ومتابعة نسب تحققها دورياً." },
                    { 208, "Common", "admission", "4.1 / 6.2", 50, "الخطة الاستراتيجية", "المواءمة الاستراتيجية ← الخطة التنفيذية السنوية ← تقارير الإنجاز : التحقق من ارتباط خطة الدائرة بالخطة الاستراتيجية للجامعة ومتابعة إنجاز الأنشطة والمشاريع المجدولة." },
                    { 209, "Common", "admission", "9.1.1", 51, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للدائرة وتحليل نتائجها واتخاذ إجراءات تحسينية." },
                    { 210, "Common", "admission", "4.1", 52, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية ← الإقرار ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات الخاصة بالدائرة." },
                    { 211, "Common", "admission", "6.1", 53, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة (مثل أتمتة الخدمات الطلابية، استقطاب الطلبة) إلى مبادرات تطويرية منفذة." },
                    { 212, "Common", "admission", "6.1", 54, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر التشغيلية والأكاديمية في القبول والتسجيل ووضع ضوابط وقائية للسيطرة عليها." },
                    { 213, "DepartmentSpecific", "admission", "8.2.2 / 8.2.3", 55, "إجراءات القبول", "إعلان أسس وشروط القبول ← تحديد الطاقة الاستيعابية والحدود الدنيا ← استقبال وتدقيق الطلبات : التحقق من وجود إجراءات قبول موثقة ومعلنة تتوافق مع أسس وزارة التعليم العالي وهيئة الاعتماد لكل تخصص." },
                    { 214, "DepartmentSpecific", "admission", "8.2.3 / 8.5.1", 56, "قبول الطلبة المستجدين", "تقديم طلب الالتحاق ← تدقيق الوثائق والمعدل ← قرار القبول وإصدار الرقم الجامعي ← الرفع للتعليم العالي : التحقق من صحة وسلامة إجراءات قبول الطلبة المستجدين واستيفائهم لكافة الشروط الرسمية." },
                    { 215, "DepartmentSpecific", "admission", "8.5.1", 57, "تسجيل الطلبة", "إعلان مواعيد التسجيل ← الإرشاد الأكاديمي ← تسجيل المواد إلكترونياً ← المصادقة المالية : التحقق من انتظام عملية تسجيل الطلبة للمواد الدراسية في كل فصل دراسي وفق خططهم الدراسية والأعباء الأكاديمية المسموحة." },
                    { 216, "DepartmentSpecific", "admission", "8.5.1", 58, "معادلة المواد", "تقديم طلب المعادلة وكشف العلامات ووصف المواد ← دراسة القسم والكلية ← التدقيق والاعتماد ← الرصد بالنظام : التحقق من أن معادلة المواد للطلبة المحسرين أو المنقولين تتم وفق أسس المعادلة المعتمدة وبقرار رسمي قبل رصدها." },
                    { 217, "DepartmentSpecific", "admission", "8.5.1 / 8.6", 59, "إدارة التسجيل", "طرح الجدول الدراسي ← إدارة السحب والإضافة والشعب ← رصد العلامات والإنذارات ← تدقيق الخريجين : التحقق من كفاءة إدارة العمليات الفصلية للتسجيل من إعداد الجدول الدراسي حتى إغلاق الفصل ورصد المعدلات والإنذارات وتدقيق التخرج." },
                    { 218, "DepartmentSpecific", "admission", "7.5.2", 60, "نماذج العمل", "تصميم النموذج ← الترميز والاعتماد من الجودة ← الإتاحة للطلبة والموظفين ← الاستخدام الفعلي : التحقق من أن جميع نماذج العمل المستخدمة في الدائرة موحدة ومرمّزة ومعتمدة (ورقياً وإلكترونياً)." },
                    { 219, "DepartmentSpecific", "admission", "7.1.3 / 8.5.1", 61, "حجز القاعات", "حصر القاعات وسعتها ← تسكين المحاضرات والامتحانات بدون تعارض ← معالجة طلبات التعديل والحجز الإضافي : التحقق من تنظيم وتخصيص القاعات التدريبية والمختبرات على الجدول الدراسي بما يتناسب مع أعداد الطلبة المسجلين ويمنع التعارض." },
                    { 220, "DepartmentSpecific", "admission", "7.5.3 / 8.5.5", 62, "حفظ ملفات الطلبة", "فتح الملف برقم الطالب ← تفقد اكتمال الوثائق الأصلية ← الحفظ في الملفات/الأرشيف والنسخ الإلكتروني : التحقق من وجود ملف متكامل ومفهرس لكل طالب محفوظ في بيئة آمنة ومؤرشف إلكترونياً." },
                    { 221, "DepartmentSpecific", "admission", "8.5.1", 63, "الحالات الخاصة( إسقاط مادة/الانسحاب ....", "تقديم الطلب ضمن المدة القانونية ← دراسة المبررات والأعذار ← الاعتماد حسب الصلاحيات ← التنفيذ على النظام : التحقق من ضبط إجراءات الحالات الأكاديمية الخاصة (إسقاط مادة، انسحاب من فصل، تأجيل دراسة، تحويل تخصص، دراسة استدراكية/بديلة)." },
                    { 222, "DepartmentSpecific", "admission", "8.5.1 / 8.6", 64, "إصدار الوثائق", "طلب الوثيقة وتسديد الرسوم ← الإعداد والتدقيق المزدوج ← التوقيع والختم الرسمي ← التسليم والتوثيق : التحقق من دقة وموثوقية وسرعة إصدار الوثائق الرسمية (كشوف العلامات، المصدقات، الشهادات الجدارية، إثباتات الدوام)." },
                    { 223, "Common", "admission", "9.1.2 / 10.2", 65, "الشكاوى", "استقبال الشكوى ← التسجيل والتصنيف ← الدراسة والمعالجة ← الرد والإجراء التصحيحي : التحقق من وجود آلية واضحة لاستقبال شكاوى الطلبة والمراجعين ومعالجتها ضمن زمن محدد واتخاذ إجراءات تصحيحية." },
                    { 224, "Common", "admission", "9.1.2", 66, "استبيانات رضا الطلبة وتحليلها", "توزيع الاستبانة ← التحليل الإحصائي ← تحديد نقاط الضعف ← تنفيذ خطة التحسين : التحقق من قياس رضا الطلبة عن خدمات القبول والتسجيل دورياً وتحليل النتائج وتحويلها إلى خطة تحسين فعلية." },
                    { 301, "Common", "hr", "5.3 / 7.2", 68, "الوصف الوظيفي", "توصيف المهام والمسؤولات ← الاعتماد ← التبليغ والتوقيع بالعلم ← المراجعة الدورية : التحقق من وجود بطاقات وصف وظيفي معتمدة لموظفي الدائرة ولكافة المسميات الوظيفية في الجامعة، وموقعة بالعلم من الموظفين." },
                    { 302, "Common", "hr", "5.2 / 7.1.2", 69, "سياسة الموارد البشرية", "الصياغة والاعتماد ← التوافق مع الأنظمة والتشريعات ← النشر والتعميم للعاملين : التحقق من وجود سياسة وأنظمة وتعليمات موارد بشرية معتمدة (للهيئة التدريسية والإدارية) تضبط الاستقطاب، التعيين، الحقوق، والواجبات." },
                    { 303, "DepartmentSpecific", "hr", "7.1.2", 70, "العدالة وتكافؤ الفرص", "إعلان الشواغر بشفافية ← معايير مفاضلة معلنة وموزونة ← حيادية لجان الاختيار والترقية : التحقق من تطبيق مبادئ العدالة، الشفافية، وتكافؤ الفرص وعدم التمييز في التعيينات، التدريب، التقييم، والترقيات." },
                    { 304, "Common", "hr", "7.1.4 / 8.5.3", 71, "بيئة العمل (السلامة العامة وخدمات ذوي الاحتياجات)", "توفير بيئة عمل آمنة وصحية ← متطلبات السلامة العامة ← التسهيلات المخصصة لذوي الاحتياجات الخاصة : التحقق من ملاءمة بيئة العمل في الدائرة ومراعاتها لشروط السلامة المهنية وتوفير التسهيلات للموظفين والمراجعين من ذوي الإعاقة." },
                    { 305, "Common", "hr", "7.5.3", 72, "ملفات الموظفين والسجلات", "فتح الملف (أكاديمي/إداري) ← اكتمال الوثائق الثبوتية ← التحديث المستمر للقرارات ← الحفظ الآمن والسري : التحقق من ضبط وحفظ ملفات العاملين وكافة سجلات الدائرة وفق نماذج الجودة المعتمدة وبسرية وأمان تام." },
                    { 306, "DepartmentSpecific", "hr", "7.1.3 / 7.5.3", 73, "نظام معلومات الموارد البشرية", "إدخال وتحديث بيانات العاملين ← أتمتة الدوام والإجازات والرواتب ← ضبط الصلاحيات والنسخ الاحتياطي : التحقق من كفاءة نظام معلومات الموارد البشرية الإلكتروني، في إدارة بيانات العاملين، (HRIS) الدوام، الإجازات، وإصدار التقارير، وتطابقه مع الملفات الورقية." },
                    { 307, "Common", "hr", "7.2", 74, "التدريب والكفاءة", "تحديد الفجوات التدريبية ← إعداد الخطة التدريبية السنوية ← تنفيذ الدورات ← قياس أثر التدريب : التحقق من إدارة الدورات التدريبية وتطوير كفاءة موظفي الدائرة وموظفي الجامعة الإداريين وقياس أثر التدريب على الأداء." },
                    { 308, "Common", "hr", "6.2", 75, "هدف الجودة", "صياغة أهداف ذكية ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس لدائرة الموارد البشرية ومتابعة نسبة إنجازها دورياً." },
                    { 309, "Common", "hr", "4.1 / 6.2", 76, "الخطة الاستراتيجية", "المواءمة الاستراتيجية ← الخطة التنفيذية السنوية ← تقارير الإنجاز : التحقق من ارتباط خطة الموارد البشرية بالخطة الاستراتيجية للجامعة ومتابعة تنفيذ أنشطتها دورياً." },
                    { 310, "Common", "hr", "9.1.1", 77, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للموارد البشرية (مثل معدل الدوران الوظيفي، نسبة الرضا الوظيفي، تنفيذ خطة التدريب)." },
                    { 311, "Common", "hr", "4.1", 78, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية ← الإقرار ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات الخاصة بالموارد البشرية." },
                    { 312, "Common", "hr", "6.1", 79, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة للموارد البشرية إلى مبادرات تطويرية مجدولة ومنفذة." },
                    { 313, "Common", "hr", "6.1", 80, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر المتعلقة بالموارد البشرية (مثل تسرب الكفاءات، نقص الكوادر، أخطاء العقود/المستحقات) وخطط السيطرة عليها." },
                    { 314, "DepartmentSpecific", "hr", "7.1.2 / 7.2", 81, "إجراءات التعيين", "طلب الاحتياج الوظيفي ← الإعلان ← والفرز ← المقابلة والاختيار ← قرار التعيين والعقد ← التهيئة ومباشرة العمل : التحقق من أن كافة التعيينات (الأكاديمية والإدارية) تمر بدورة استقطاب واختيار وتعيين وتهيئة موثقة ومطابقة للتعليمات ومعايير الاعتماد." },
                    { 315, "Common", "hr", "7.2 / 9.1", 82, "تقييم الأداء الوظيفي", "تعميم نماذج التقييم السنوي ← التقييم من المسؤول المباشر ← الاعتماد وإبلاغ الموظف ← ربط النتائج بالتدريب والترقية : التحقق من إجراء تقييم أداء سنوي دوري وموضوعي للمعلمين، وإتاحة حق التظلم، واستخدام المخرجات في خطط التطوير والترقيات وتجديد العقود." },
                    { 316, "Common", "hr", "9.1.2 / 10.2", 83, "إدارة الشكاوى الوظيفية واستبيانات الرضا عن الخدمات", "استقبال الشكوى/التظلم الوظيفي ومعالجته ← توزيع استبيانات الرضا ← التحليل الإحصائي ← خطة التحسين : التحقق من وجود آلية عادلة لمعالجة الشكاوى والتظلمات الوظيفية، وقياس رضا العاملين عن خدمات الدائرة والرضا الوظيفي وتحويل النتائج لخطط تحسين." },
                    { 401, "Common", "presidency", "4.3 / 5.3", 85, "نطاق أعمال الديوان", "تحديد المهام والعمليات ← الهيكل التنظيمي والوصف الوظيفي ← الاعتماد والتعميم : التحقق من وضوح وتوثيق نطاق عمل ديوان الرئاسة وحدود صلاحياته ومسؤولياته التنظيمية والإدارية في الجامعة." },
                    { 402, "DepartmentSpecific", "presidency", "5.1 / 7.4", 86, "حوكمة القرارات", "إعداد القرار الرئاسي/الإداري ← التدقيق القانوني والإداري ← الاعتماد والتوقيع ← التعميم ومتابعة التنفيذ : التحقق من انضباط دورة إصدار القرارات والتعاميم الرئاسية ومجالس الجامعة وتوثيقها وإبلاغها للجهات المعنية." },
                    { 403, "DepartmentSpecific", "presidency", "6.1 / 8.1", 87, "التركيز على استراتيجية الخدمة", "تحديد المخاطر التشغيلية ← خطط الطوارئ والبدائل ← عدم انقطاع البريد والمراسلات : التحقق من وجود إجراءات تضمن عدم توقف أعمال الديوان (الوارد، الصادر، القرارات العاجلة) في حالات الطوارئ أو تعطّل النظام أو غياب الموظف المختص." },
                    { 404, "DepartmentSpecific", "presidency", "7.4 / 8.5.1", 88, "ضبط المراسلات الرسمية", "الاستلام/الإعداد ← التدقيق الشكلي واللغوي ← الترقيم والتأريخ والختم ← التوجيه والإرسال : التحقق من ضبط دورة البريد الوارد والصادر (الداخلي والخارجي) وفق الأصول الإدارية والتسلسل الوظيفي المعتمد." },
                    { 405, "DepartmentSpecific", "presidency", "7.1.3 / 7.5.3", 89, "نظام الأرشفة الإلكتروني", "المسح الضوئي (Scanning) ← إدخال البيانات الوصفية (Metadata) ← الربط الموضوعي ← النسخ الاحتياطي : التحقق من فاعلية نظام الأرشفة الإلكتروني في حفظ وفهرسة وربط الكتب الرسمية وسهولة البحث عنها." },
                    { 406, "Common", "presidency", "7.5.3", 90, "حفظ السجلات", "التصنيف والترميز ← الحفظ الورقي والإلكتروني الآمن ← تطبيق مدد الحفظ القانونية : التحقق من حفظ السجلات والملفات الرسمية في بيئة آمنة تحميها من التلف أو الضياع أو العبث." },
                    { 407, "Common", "presidency", "7.2", 91, "التدريب والكفاءة", "حصر الاحتياج التدريبي ← خطة التدريب ← التنفيذ ← تقييم أثر التدريب : التحقق من كفاءة موظفي الديوان وتدريبهم على الأرشفة الحديثة، الصياغة الإدارية، وأمن الوثائق، وقياس أثر التدريب." },
                    { 408, "Common", "presidency", "7.5.2 / 7.5.3", 92, "آلية ضبط الوثائق", "إعداد الوثيقة/النموذج ← الترميز والاعتماد من الجودة ← استخدام الإصدار الساري ← إلغاء القديم : التحقق من التزام الديوان بآلية ضبط الوثائق والنماذج المعتمدة في نظام إدارة الجودة بالجامعة." },
                    { 409, "DepartmentSpecific", "presidency", "7.5.3", 93, "سهولة الوصول للملفات", "خطة التصنيف والفهرسة ← الترقيم المعياري للأضابير ← سرعة الاسترجاع الفعلي : التحقق من تنظيم وفهرسة الملفات الموضوعية والزمنية بحيث يمكن الوصول لأي كتاب أو قرار في أسرع وقت." },
                    { 410, "Common", "presidency", "7.5.3 / 8.5.5", 94, "أمن المعلومات", "تصنيف سرية المراسلات ← تحديد صلاحيات الدخول والاطلاع ← ضبط تعهدات السرية ← تطبيق الأختام : التحقق من حماية سرية المراسلات والقرارات الرئاسية وعدم وصول غير المخولين إليها، وضبط حيازة الأختام الرسمية." },
                    { 411, "Common", "presidency", "9.1.2 / 10.2", 95, "الشكاوى", "استقبال الشكوى/الملاحظة ← الدراسة والمعالجة ← الرد والإجراء التصحيحي : التحقق من وجود آلية واضحة لاستقبال ومعالجة الشكاوى والملاحظات المتعلقة بخدمات الديوان وتأخر أو أخطاء المراسلات." },
                    { 501, "Common", "student_affairs", "5.3 / 7.2", 97, "الوصف الوظيفي", "توصيف المهام ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة لجميع المسميات الوظيفية في العمادة وتوقيع الموظفين عليها." },
                    { 502, "Common", "student_affairs", "5.2", 98, "السياسة التعليمية", "الصياغة والاعتماد ← النشر للطلبة والعاملين ← التطبيق في البرامج والأنشطة : التحقق من توافر وإعلان السياسة التعليمية وتعليمات شؤون الطلبة وميثاق شرف الطالب، وانعكاسها في أنشطة العمادة." },
                    { 503, "Common", "student_affairs", "7.1.4", 99, "بيئة العمل (السلامة العامة والخدمات العامة)", "تهيئة المرافق والصالات والملاعب ← التفقد الدوري للسلامة والنظافة والصيانة : التحقق من توافر شروط السلامة العامة والجاهزية في مكاتب العمادة، المرافق الرياضية، المسارح، والمرافق الخدمية للطلبة." },
                    { 504, "Common", "student_affairs", "7.5.2 / 7.5.3", 100, "ضبط الوثائق وحفظ السجلات", "الترميز والاعتماد ← استخدام النموذج الساري ← الفهرسة والحفظ الآمن ← مدة الحفظ : التحقق من ضبط كافة الوثائق والسجلات الإدارية والطلابية وفق نظام إدارة الجودة." },
                    { 505, "Common", "student_affairs", "6.2", 101, "هدف الجودة", "صياغة أهداف ذكية ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس للعمادة ومتابعة نسبة إنجازها دورياً." },
                    { 506, "Common", "student_affairs", "4.1 / 6.2", 102, "الخطة الاستراتيجية", "المواءمة الاستراتيجية ← الخطة التنفيذية السنوية ← تقارير الإنجاز : التحقق من ارتباط خطة العمادة بالخطة الاستراتيجية للجامعة ومتابعة تنفيذ مشاريعها وأنشطتها دورياً." },
                    { 507, "Common", "student_affairs", "9.1.1", 103, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للعمادة وتحليل نتائجها واتخاذ إجراءات تحسينية." },
                    { 508, "Common", "student_affairs", "4.1", 104, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية ← الإقرار ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات الخاصة بالعمادة." },
                    { 509, "Common", "student_affairs", "6.1", 105, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة للعمادة إلى مبادرات تطويرية مجدولة ومنفذة." },
                    { 510, "Common", "student_affairs", "6.1", 106, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر المتعلقة بالأنشطة والتجمعات الطلابية والمرافق ووضع خطط وقائية للسيطرة عليها." },
                    { 511, "Common", "student_affairs", "8.5.1 / 9.1.2", 107, "متابعة الخريجين", "تحديث قاعدة بيانات الخريجين ← التأهيل الوظيفي والأيام المهنية ← تتبع التشغيل ← قياس رضا الخريجين وأرباب العمل : التحقق من وجود آلية فاعلة للتواصل مع الخريجين، وتأهيلهم لسوق العمل، ورصد نسبة توظيفهم." },
                    { 512, "DepartmentSpecific", "student_affairs", "8.5.1", 108, "الأنشطة الطلابية رياضية/ثقافية/خدمة مجتمع", "الخطة الفصلية للأنشطة ← الإعلان والموافقة ← التنفيذ والتوثيق ← تقييم النشاط : التحقق من تخطيط وتنفيذ وتوثيق الأنشطة الرياضية والثقافية والفنية ومبادرات خدمة المجتمع والعمل التطوعي." },
                    { 513, "DepartmentSpecific", "student_affairs", "8.5.1", 109, "الأندية الطلابية", "تشكيل/ترخيص النادي ← اعتماد خطة العمل ← الإشراف والمتابعة ← التقرير الفصلي : التحقق من تنظيم عمل الأندية الطلابية والجاليات والهيئات الطلابية والإشراف على انتخاباتها وأنشطتها وفق التعليمات." },
                    { 514, "DepartmentSpecific", "student_affairs", "8.5.1 / 8.5.5", 110, "الإرشاد الطلابي", "استقبال الحالة/المشكلة ← الجلسات الإرشادية بسرية ← خطة المعالجة والدعم ← المتابعة والتقييم : التحقق من تقديم خدمات الإرشاد النفسي والاجتماعي والتربوي والسلوكي للطلبة مع الحفاظ التام على سرية بياناتهم." },
                    { 515, "Common", "student_affairs", "9.1.2 / 10.2", 111, "الشكاوى والمقترحات", "استقبال الشكوى/المقترح ← التسجيل ← الدراسة والمعالجة ← الرد والإجراء التصحيحي : التحقق من وجود قنوات معلنة لاستقبال شكاوى ومقترحات الطلبة ومعالجتها ضمن سقف زمني محدد." },
                    { 516, "DepartmentSpecific", "student_affairs", "8.5.1", 112, "المنح والمساعدات", "الإعلان عن تقديم الطلبات ← دراسة الوثائق والمعايير الاجتماعية/الأكاديمية ← تنسيب اللجنة ← قرار الصرف/المنحة : التحقق من عدالة وشفافية إجراءات دراسة ومنح المساعدات المالية والقروض والمنح الطلابية وتشغيل الطلبة وفق الأسس المعتمدة." },
                    { 517, "DepartmentSpecific", "student_affairs", "8.5.3", 113, "دعم ذوي الاحتياجات الخاصة", "حصر الطلبة ذوي الإعاقة ← تقييم الاحتياجات الفردية ← توفير التسهيلات الأكاديمية والبيئية ← المتابعة الدورية : التحقق من وجود قاعدة بيانات محدثة للطلبة ذوي الاحتياجات الخاصة وتقديم برامج الدعم والدمج والتسهيلات اللازمة لهم." },
                    { 518, "DepartmentSpecific", "student_affairs", "7.1.3", 114, "الموارد والتجهيزات", "حصر الموارد والتجهيزات ← توفير المستلزمات ← الصيانة الدورية والجرد ← ضبط العهدة : التحقق من كفاءة وجاهزية الموارد والتجهيزات الرياضية والفنية والمسرحية والخدمية في العمادة وصيانتها وضبط عهدتها." },
                    { 519, "Common", "student_affairs", "9.1.2", 115, "استبيانات رضا الطلبة وتحليلها", "توزيع الاستبانة ← التحليل الإحصائي ← تحديد نقاط الضعف ← تنفيذ خطة التحسين : التحقق من قياس رضا الطلبة الدوري عن خدمات وأنشطة عمادة شؤون الطلبة وتحليل النتائج وتحويلها لخطة تحسين." },
                    { 601, "Common", "it_center", "5.3 / 7.2", 117, "الوصف الوظيفي", "توصيف المهام ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة لجميع المسميات التقنية والبرمجية والإدارية وتوقيع الموظفين عليها." },
                    { 602, "Common", "it_center", "5.2 / 7.1.3", 118, "سياسة وتعليمات مركز الحاسوب", "الصياغة والاعتماد ← التعميم للمستخدمين ← التطبيق والمتابعة : التحقق من وجود سياسة وتعليمات معتمدة لمركز الحاسوب تضبط استخدام الشبكة، الأنظمة، المختبرات، والبريد الإلكتروني الجامعي." },
                    { 603, "DepartmentSpecific", "it_center", "6.1 / 8.1", 119, "التركيز على استمرارية الخدمة", "مراقبة الأنظمة (24/7) ← النسخ الاحتياطي وتكرار الخوادم (Redundancy) ← خطة التعافي من الكوارث (DRP) : التحقق من الإجراءات التقنية لضمان استمرارية عمل الأنظمة الجامعية والشبكة والإنترنت دون انقطاع وسرعة استعادتها عند الطوارئ." },
                    { 604, "DepartmentSpecific", "it_center", "7.5.2 / 8.3", 120, "ضبط الأنظمة والوثائق", "توثيق الأنظمة البرمجية ← ضبط التعديلات والإصدارات (Change Management) ← ترميز واعتماد الوثائق : التحقق من ضبط وتوثيق الأنظمة البرمجية وأدلة الاستخدام وكافة الوثائق والنماذج وفق معايير الجودة." },
                    { 605, "Common", "it_center", "7.5.3", 121, "حفظ السجلات", "تعيين السجل المعتمد ← الفهرسة والأرشفة ← الحفظ الآمن وتطبيق مدة الحفظ : التحقق من أرشفة وحفظ كافة السجلات التقنية والإدارية (سجلات الصيانة، الصلاحيات، الخوادم، البلاغات) بأمان." },
                    { 606, "Common", "it_center", "7.2", 122, "التدريب والكفاءة", "حصر الاحتياج التدريبي ← خطة التدريب ← التنفيذ ← قياس أثر التدريب : التحقق من كفاءة الكادر التقني والبرمجي وتدريبهم المستمر على أحدث التقنيات وأمن المعلومات وتقييم أثر التدريب." },
                    { 607, "DepartmentSpecific", "it_center", "7.1.3 / 8.5.1", 123, "النظام الإلكتروني", "تحليل المتطلبات ← التطوير والتكامل بين الأنظمة ← فحص القبول (UAT) والتشغيل والتحديث : التحقق من كفاءة وتكامل الأنظمة الإلكترونية الجامعية (القبول والتسجيل، المالية، الموارد البشرية، البوابة، الموقع) وتلبيتها لمتطلبات العمل." },
                    { 608, "Common", "it_center", "4.1 / 6.2", 124, "الخطة الاستراتيجية", "المواءمة الاستراتيجية ← الخطة التنفيذية السنوية وأهداف الجودة ← تقارير الإنجاز : التحقق من ارتباط خطة مركز الحاسوب وأهدافه بالخطة الاستراتيجية للجامعة (التحول الرقمي) ومتابعة إنجازها." },
                    { 609, "Common", "it_center", "9.1.1", 125, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للمركز (نسبة جاهزية الأنظمة Uptime، سرعة إغلاق تذاكر الدعم، إنجاز الأمتمة)." },
                    { 610, "Common", "it_center", "4.1", 126, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية ← الإقرار ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات الخاصة بمركز الحاسوب." },
                    { 611, "Common", "it_center", "6.1", 127, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة إلى مبادرات تطويرية مجدولة ومنفذة." },
                    { 612, "Common", "it_center", "6.1", 128, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر التقنية والسيبرانية والتشغيلية وتطبيق ضوابط السيطرة عليها." },
                    { 613, "DepartmentSpecific", "it_center", "8.5.1", 129, "إدارة الدعم الفني", "استلام بلاغ العطل (Help Desk) ← التصنيف والتوجيه الفني ← الإصلاح ← إغلاق الطلب بتأكيد المستفيد : التحقق من تنظيم واستجابة قسم الدعم الفني لبلاغات الأعطال ومتابعة زمن الحل." },
                    { 614, "DepartmentSpecific", "it_center", "7.1.3", 130, "صيانة البنية التحتية", "حصر الأصول التقنية ← خطة الصيانة الوقائية الدورية ← فحص غرفة الخوادم والمختبرات ← التوثيق : التحقق من تنفيذ الصيانة الوقائية الدورية للخوادم، مقاسم الشبكة، خطوط الإنترنت، ومختبرات الحاسوب قبل وخلال الفصول الدراسية." },
                    { 615, "Common", "it_center", "7.5.3 / 8.5.5", 131, "أمن المعلومات", "جدران الحماية ومكافحة الفيروسات ← إدارة الصلاحيات وكلمات المرور ← فحص الثغرات ← الاستجابة للحوادث : التحقق من تطبيق ضوابط الأمن السيبراني لحماية الشبكة والخوادم وقواعد البيانات ومنع الوصول غير المصرح به." },
                    { 616, "Common", "it_center", "9.1.2 / 10.2", 132, "الشكاوى", "استقبال الشكوى ← التوثيق ← التحقيق والمعالجة الجذرية ← الرد والإجراء التصحيحي : التحقق من وجود آلية واضحة لاستقبال ومعالجة شكاوى المستفيدين حول خدمات المركز والأنظمة والشبكة." },
                    { 617, "Common", "it_center", "9.1.2", 133, "استبيانات رضا أصحاب العلاقة وتحليلها", "توزيع الاستبانة ← التحليل الإحصائي ← تحديد فرص التحسين ← تنفيذ خطة التحسين : التحقق من قياس رضا أصحاب العلاقة (طلبة، إداريين) عن خدمات مركز الحاسوب وتحويل النتائج لخطة تحسين." },
                    { 701, "Common", "quality_unit", "5.3 / 7.2", 135, "الوصف الوظيفي", "توصيف المهام والصلاحيات ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة لجميع العاملين في وحدة الجودة وتوقيعهم بالاستلام والعلم." },
                    { 702, "Common", "quality_unit", "5.2", 136, "سياسة نظام ادارة المؤسسات التعليمية", "الصياغة وفق متطلبات ISO 21001 ← الاعتماد من رئيس الجامعة ← النشر والتعميم ← المراجعة الدورية : التحقق من وجود سياسة معتمدة لنظام إدارة المؤسسات التعليمية (EOMS Policy) شاملة للالتزامات الموآصفة ومعلنة لكافة المعنيين." },
                    { 703, "Common", "quality_unit", "7.5.1 / 7.5.2 / 7.5.3", 137, "الأنظمة والوثائق و حفظ السجلات", "إجراء ضبط الوثائق والسجلات ← الترميز والاعتماد المركزي ← القائمة الرئيسية (Master List) ← ضبط التعديلات والإلغاء : التحقق من قيادة الوحدة لضبط كافة الوثائق وإجراءات ونماذج وسجلات نظام الجودة على مستوى الجامعة وحفظها بأمان." },
                    { 704, "DepartmentSpecific", "quality_unit", "7.2", 138, "الخطة التدريبية- تطوير اعضاء هيئة التدريس", "حصر الاحتياجات التطويرية ← إعداد خطة التطوير الأكاديمي ← تنفيذ الورش والدورات ← تقييم الفعالية والأثر : التحقق من إعداد وتنفيذ خطة تدريبية شاملة لتطوير قدرات أعضاء هيئة التدريس (الجدد والقدامى) في التدريس، التقييم، البحث، والجودة." },
                    { 705, "DepartmentSpecific", "quality_unit", "6.2", 139, "اهداف الجودة", "صياغة أهداف الجودة على مستوى الجامعة والوحدة ← خطط العمل ← الرصد والقياس الدوري : التحقق من وضع أهداف جودة ذكية وقابلة للقياس على مستوى الجامعة ووحدة الجودة ومتابعة نسبة تحققها." },
                    { 706, "Common", "quality_unit", "4.1 / 6.2", 140, "الخطة الاستراتيجية- للجامعة", "الإعداد التشاركي للخطة الاستراتيجية ← الاعتماد من مجالس الحاكمة ← الخطط التنفيذية ← تقارير المتابعة : التحقق من إدارة ومتابعة الخطة الاستراتيجية للجامعة وربط خطط الكليات والدوائر بها ورصد نسبة إنجازها." },
                    { 707, "Common", "quality_unit", "9.1.1", 141, "مؤشرات الأداء للجامعة", "اعتماد دليل مؤشرات الأداء المؤسسية ← جمع البيانات من الجهات ← التحليل والمقارنة المرجعية ← خطط التحسين : التحقق من قياس وتحليل مؤشرات الأداء الرئيسية للجامعة (KPIs) ومقارنتها بالمستهدفات واتخاذ إجراءات تحسينية." },
                    { 708, "Common", "quality_unit", "4.1 / 4.2", 142, "تحليل SWOT للجامعة", "رصد العوامل الداخلية والخارجية وتأثيرات المعنيين ← إعداد مصفوفة SWOT للجامعة ← الاعتماد والتحديث : التحقق من إجراء تحليل شامل لسياق الجامعة الداخلي والخارجي وتحديثه دورياً بمشاركة أصحاب العلاقة." },
                    { 709, "Common", "quality_unit", "6.1", 143, "خطة الفرص للجامعة", "استخلاص الفرص الاستراتيجية ← إعداد خطة استثمار الفرص للجامعة ← متابعة التنفيذ والأثر : التحقق من تحويل الفرص المؤسسية للجامعة إلى مبادرات ومشاريع تطويرية ومتابعة إنجازها." },
                    { 710, "Common", "quality_unit", "6.1", 144, "إدارة المخاطر للجامعة", "تحديد المخاطر المؤسسية ← تحليل وتقييم (الاحتمالية × الأثر) ← خطط المعالجة والتحكم ← المراجعة الدورية : التحقق من وجود منهجية وسجل مخاطر مؤسسي شامل للجامعة ومتابعة كفاءة إجراءات السيطرة على المخاطر." },
                    { 711, "DepartmentSpecific", "quality_unit", "9.2", 145, "التدقيق الداخلي", "البرنامج السنوي للتدقيق ← خطة التدقيق وتأهيل المدققين (مع الاستقلالية) ← تنفيذ التدقيق بقوائم الفحص ← تقارير التدقيق ومتابعتها : التحقق من تخطيط وتنفيذ برنامج تدقيق داخلي شامل وموضوعي يغطي كافة الكليات والدوائر دون أن يدقق المدقق على عمله الخاص." },
                    { 712, "DepartmentSpecific", "quality_unit", "9.3", 146, "المراجعة الإدارية", "إعداد مدخلات المراجعة الإدارية (بند 9.3.2) ← عقد اجتماع الإدارة العليا ← إصدار مخرجات وقرارات التحسين والموارد (بند 9.3.3) : التحقق من عقد اجتماعات المراجعة الإدارية لنظام إدارة المؤسسات التعليمية برئاسة الإدارة العليا وبكافة المدخلات والمخرجات الإلزامية في المواصفة." },
                    { 713, "Common", "quality_unit", "10.2", 147, "عدم المطابقة", "رصد حالة عدم المطابقة (NCR) ← التوثيق والتصنيف ← التصحيح الفوري (Correction) ← المتابعة : التحقق من وجود إجراء وسجل لضبط وحصر كافة حالات عدم المطابقة المرصودة (من التدقيق أو الشكاوى أو العمليات) والتعامل الفوري معها." },
                    { 714, "DepartmentSpecific", "quality_unit", "10.2.1", 148, "تحليل الأسباب", "دراسة حالة عدم المطابقة ← تطبيق أدوات تحليل السبب الجذري (مثل 5 Whys / Fishbone) ← تحديد السبب الحقيقي : التحقق من أن معالجة حالات عدم المطابقة لا تقتصر على معالجة الأعراض السطحية، بل تستند لتحليل علمي للسبب الجذري لمنع التكرار." },
                    { 715, "Common", "quality_unit", "10.1 / 10.2", 149, "الإجراءات التصحيحية والتحسين المستمر", "وضع خطة الإجراء التصحيحي ← التنفيذ ضمن المهلة ← التحقق من فاعلية الإجراء وإغلاق الحالة ← مشاريع التحسين المستمر : التحقق من تنفيذ الإجراءات التصحيحية، وفحص فاعليتها بعد التنفيذ لضمان عدم تكرار المشكلة، وتوثيق مبادرات التحسين المستمر في الجامعة." },
                    { 801, "Common", "postgraduate", "5.3 / 7.2", 151, "الوصف الوظيفي", "توصيف المهام والصلاحيات ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة لجميع المسميات الوظيفية في العمادة وتوقيع الموظفين عليها." },
                    { 802, "Common", "postgraduate", "5.2", 152, "سياسة ادارة المؤسسات التعليمية", "الإعلان والتعميم ← الفهم والاستيعاب ← التطبيق في برامج الدراسات العليا : التحقق من توافر وإعلان سياسة نظام إدارة المؤسسات التعليمية وتعليمات منح درجة الماجستير/الدراسات العليا المعتمدة." },
                    { 803, "DepartmentSpecific", "postgraduate", "8.5.1", 153, "الإشراف الأكاديمي", "توزيع الطلبة على المرشدين الأكاديميين ← متابعة الخطة الدراسية والعبء ← معالجة التعثر الأكاديمي : التحقق من تفعيل الإرشاد الأكاديمي لطلبة الدراسات العليا منذ قبولهم وحتى اختيار مسار الرسالة أو المشروع الشامل." },
                    { 804, "Common", "postgraduate", "7.5.2 / 7.5.3", 154, "حفظ السجلات", "استخدام النماذج المرمّزة المعتمدة ← الفهرسة والأرشفة الآمنة ← تطبيق مدة الحفظ : التحقق من ضبط وحفظ كافة السجلات والملفات والنماذج الخاصة بطلبة وقرارات الدراسات العليا وفق نظام الجودة." },
                    { 805, "Common", "postgraduate", "6.2", 155, "هدف الجودة", "صياغة أهداف ذكية ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس لعمادة الدراسات العليا ومتابعة نسب تحققها دورياً." },
                    { 806, "Common", "postgraduate", "4.1 / 6.2", 156, "الخطة الاستراتيجية", "المواءمة الاستراتيجية ← الخطة التنفيذية السنوية ← تقارير الإنجاز : التحقق من ارتباط خطة عمادة الدراسات العليا بالخطة الاستراتيجية للجامعة ومتابعة تنفيذ أنشطتها ومشاريعها دورياً." },
                    { 807, "Common", "postgraduate", "9.1.1", 157, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للدراسات العليا وتحليل نتائجها واتخاذ إجراءات تحسينية." },
                    { 808, "Common", "postgraduate", "4.1", 158, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية ← الإقرار ← التحديد الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات الخاصة بالدراسات العليا." },
                    { 809, "Common", "postgraduate", "6.1", 159, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة (مثل استحداث برامج ماجستير نوعية، استقطاب طلبة دوليين) إلى خطة عمل منفذة." },
                    { 810, "Common", "postgraduate", "6.1", 160, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر الأكاديمية والإدارية في برامج الدراسات العليا ووضع ضوابط وقائية للسيطرة عليها." },
                    { 811, "DepartmentSpecific", "postgraduate", "7.1.3 / 7.1.6", 161, "الموارد التعليمية", "حصر متطلبات البرامج (مختبرات، برمجيات، مراجع، قواعد بيانات) ← التوريد بالتنسيق مع الكليات والمكتبة ← تقييم الكفاية : التحقق من توافر وكفاية الموارد التعليمية والبحثية والقاعات والمختبرات وقواعد البيانات اللازمة لبرامج الدراسات العليا." },
                    { 812, "Common", "postgraduate", "7.2", 162, "التدريب والكفاءة", "حصر الاحتياج التدريبي ← خطة التدريب ← التنفيذ ← قياس أثر التدريب : التحقق من تدريب كادر العمادة وتنظيم ورش تدريبية لطلبة الدراسات العليا (منهجية البحث، الكتابة العلمية، الاقتباس) وتقييم أثرها." },
                    { 813, "DepartmentSpecific", "postgraduate", "8.2.2 / 8.2.3", 163, "القبول والتسجيل", "إعلان شروط القبول والطاقة الاستيعابية ← استقبال الطلبات ← تدقيق الشروط والمفاضلة في القسم والعمادة ← قرار القبول والتسجيل : التحقق من سلامة وعدالة إجراءات قبول وتسجيل طلبة الدراسات العليا والتزامهم بشروط اللغة والقبول المعتمدة." },
                    { 814, "DepartmentSpecific", "postgraduate", "8.3", 164, "اعتماد الخطط الدراسية", "إعداد/مراجعة الخطة في القسم والكلية ← دراسة مجلس الدراسات العليا ← اعتماد مجلس العمادة وهيئة الاعتماد ← النشر والتطبيق : التحقق من أن جميع الخطط الدراسية لبرامج الدراسات العليا معتمدة أصولياً ومحدثة وتغطي مخرجات التعلم (مسار الرسالة والشامل)." },
                    { 815, "DepartmentSpecific", "postgraduate", "8.5.1", 165, "الإشراف على الرسائل", "تقديم مشروع الخطة (Proposal) ← التحقق من الأصالة وعدم التكرار ← قرار تعيين المشرف واعتماد العنوان ← تقارير متابعة الإنجاز الفصلية : التحقق من انضباط إجراءات تسمية المشرفين (ومراعاة نصاب الإشراف والرتبة الأكاديمية)، واعتماد خطط الرسائل، ومتابعة تقدم الطالب." },
                    { 816, "DepartmentSpecific", "postgraduate", "8.5.1 / 8.6", 166, "مناقشة الرسائل", "تقرير جاهزية الرسالة وفحص الاستلال (Turnitin) ← تشكيل لجنة المناقشة ← لجنة المناقشة العلنية والتقييم ← تعديلات ما بعد المناقشة ← إيداع النسخة النهائية ← منح الدرجة : التحقق من سلامة سلسلة إجراءات مناقشة الرسائل الجامعية وفحص الاقتباس العلمي وإجازة الرسالة قبل التنسيب بمنح الدرجة." },
                    { 817, "Common", "postgraduate", "8.5.1 / 9.1.2", 167, "متابعة الخريجين", "قاعدة بيانات خريجي الدراسات العليا ← التواصل وتتبع المسار المهني والبحثي ← التغذية الراجعة لتطوير البرامج : التحقق من وجود قاعدة بيانات محدثة لخريجي برامج الدراسات العليا ومتابعة تطورهم الوظيفي والأكاديمي." },
                    { 818, "Common", "postgraduate", "9.1.2", 168, "استبيانات رضا اصحاب العلاقة وتحليلها", "توزيع الاستبيانات (طلبة، مشرفين، خريجين) ← التحليل الإحصائي ← تحديد فرص التحسين ← تنفيذ خطة التحسين : التحقق من قياس رضا أصحاب العلاقة عن برامج وخدمات الدراسات العليا وتحليل النتائج وتحويلها لخطط تحسين." },
                    { 901, "Common", "faculties", "5.3 / 7.2", 170, "الوصف الوظيفي", "توصيف المهام والصلاحيات ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة (العميد، نائب/مساعد العميد، رؤساء الأقسام، أعضاء هيئة التدريس، مشرفي المختبرات، الإداريين) وموقعة بالعلم." },
                    { 902, "Common", "faculties", "5.2", 171, "سياسة ادارة المؤسسات التعليمية", "الإعلان والنشر في الكلية ← التوعية والاستيعاب ← التطبيق في التدريس والتقييم : التحقق من إعلان سياسة نظام إدارة المؤسسات التعليمية (ورؤية ورسالة وأهداف الكلية) ومعرفة الكادر والطلبة بها." },
                    { 903, "Common", "faculties", "7.1.4 / 8.5.3", 172, "بيئة العمل (سلامة عامة وخدمات ذوي الاحتياجات الخاصة ...)", "تفقد القاعات والمختبرات والمرافق ← تطبيق شروط السلامة العامة ← توفير التسهيلات الأكاديمية والبيئية لذوي الاحتياجات الخاصة : التحقق من جاهزية القاعات التدريسية والمختبرات والمكاتب وتوافر متطلبات السلامة وتسهيلات الطلبة ذوي الإعاقة." },
                    { 904, "Common", "faculties", "7.5.2 / 7.5.3", 173, "ضبط الوثائق وحفظ السجلات", "الترميز والاعتماد ← استخدام النماذج السارية ← الفهرسة والأرشفة الآمنة ← مدة الحفظ : التحقق من التزام العمادة والأقسام الأكاديمية بضبط الوثائق وحفظ السجلات (محاضر المجالس، ملفات المساقات، ملفات الإرشاد) وفق نظام الجودة." },
                    { 905, "Common", "faculties", "7.2", 174, "التدريب والكفاءة", "حصر الاحتياجات التدريبية (للكادر الأكاديمي والإداري والفني) ← خطة التدريب ← المشاركة الفعلية ← قياس أثر التدريب : التحقق من تأهيل وتدريب أعضاء هيئة التدريس ومشرفي المختبرات والإداريين في الكلية وتقييم انعكاس التدريب على أدائهم." },
                    { 906, "Common", "faculties", "6.2", 175, "هدف الجودة", "صياغة أهداف ذكية للكلية والأقسام ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس للكلية ومنسجمة مع أهداف الجامعة، ومتابعة نسب تحققها." },
                    { 907, "Common", "faculties", "4.1 / 6.2", 176, "الخطة الاستراتيجية", "إعداد خطة الكلية الاستراتيجية المتوافقة مع استراتيجية الجامعة ← الاعتماد ← المراجعة الدورية : التحقق من وجود خطة استراتيجية معتمدة للكلية تنبثق من الخطة الاستراتيجية للجامعة وتغطي التعليم والبحث وخدمة المجتمع." },
                    { 908, "Common", "faculties", "9.1.1", 177, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات الأداء الرئيسية للكلية وبرامجها الأكاديمية وتحليل الفجوات واتخاذ إجراءات تحسينية." },
                    { 909, "DepartmentSpecific", "faculties", "6.2 / 8.1", 178, "الخطة التنفيذية", "ترجمة الخطة الاستراتيجية إلى خطة تنفيذية سنوية ← توزيع المهام والأزمان والموارد ← تقارير الإنجاز الدورية : التحقق من وجود خطة تنفيذية سنوية للكلية وأقسامها الأكاديمية ومتابعة نسب إنجاز أنشطتها." },
                    { 910, "Common", "faculties", "4.1", 179, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية للكلية ← الإقرار في مجلس الكلية ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات للكلية وبرامجها." },
                    { 911, "Common", "faculties", "6.1", 180, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص المتاحة للكلية (اعتمادات دولية، شراكات مهنية، برامج جديدة) إلى مبادرات تطويرية منفذة." },
                    { 912, "Common", "faculties", "6.1", 181, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية × الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد المخاطر الأكاديمية والتشغيلية والمخبرية في الكلية ووضع خطط وقائية للسيطرة عليها." },
                    { 913, "DepartmentSpecific", "faculties", "8.1 / 9.1", 182, "البحث العلمي", "الخطة البحثية للأقسام ← تشجيع ومتابعة نشر الأبحاث المحكمة ← المؤتمرات والندوات العلمية ← رصد الإنتاج البحثي : التحقق من متابعة الكلية للنشاط البحثي لأعضاء هيئة التدريس، ونشر الأبحاث في قواعد البيانات العالمية (Scopus/WoS)، والمشاركات العلمية." },
                    { 914, "Common", "faculties", "8.5.1 / 9.1.2", 183, "متابعة الخريجين", "حصر خريجي الكلية ← التواصل واللقاءات المهنية ← رصد نسب التوظيف ← استطلاع رأي الخريجين وأرباب العمل : التحقق من متابعة الكلية لخريجيها وإشراكهم مع أرباب العمل في تطوير الخطط والبرامج الدراسية." },
                    { 915, "DepartmentSpecific", "faculties", "8.5.1", 184, "التعليم الإلكتروني", "رفع خطة ومحتوى المساق على المنصة ← الواجبات والأنشطة التفاعلية ← متابعة تفاعل الطلبة والمدرسين : التحقق من توظيف منصة التعلم الإلكتروني بفاعلية في كافة مساقات الكلية ومتابعة التزام المدرسين بمعايير المحتوى الإلكتروني." },
                    { 916, "DepartmentSpecific", "faculties", "8.3", 185, "آلية تصميم وتطوير البرامج الدراسية", "دراسة حاجة سوق العمل والمقارنة المرجعية ← صياغة مخرجات التعلم (PLOS) والخطة الدراسية ← إقرار القسم والكلية ← الاعتماد الرسمي والمراجعة الدورية : التحقق من أن تصميم البرامج الدراسية أو تحديث الخطط الدراسية يتم وفق منهجية علمية تشارك أصحاب العلاقة وتغطي معايير الاعتماد." },
                    { 917, "DepartmentSpecific", "faculties", "8.5.1", 186, "آلية طرح المساقات في الفصول الدراسية", "دراسة إحصائيات الطلبة والخطط الإرشادية ← إعداد الجدول الدراسي وتوزيع الأعباء التدريسية حسب التخصص ← إقرار القسم والكلية ← إرسال الجدول للقبول والتسجيل : التحقق من التخطيط السليم لطرح المساقات وتوزيعها على أعضاء هيئة التدريس وفق تخصصاتهم الدقيقة ونصابهم التدريسي." },
                    { 918, "DepartmentSpecific", "faculties", "8.5.1 / 8.6", 187, "آلية إعداد الامتحانات ورصد النتائج", "إعداد أسئلة الامتحان وفق جدول المواصفات ومخرجات التعلم ← التدقيق والاعتماد من رئيس القسم/منسق المادة ← ضبط المراقبات والتصحيح ← تدقيق ورصد العلامات : التحقق من جودة وعدالة الامتحانات وارتباطها بمخرجات التعلم، وضبط إجراءات المراقبة والتصحيح والمراجعة قبل إعلان ورصد النتائج." },
                    { 919, "DepartmentSpecific", "faculties", "9.1.1 / 9.1.3", 188, "تحليل النتائج إحصائيًا", "استخراج التوزيع التكراري للعلامات ونسب النجاح والرسوب ← قياس تحقق مخرجات التعلم ← مناقشة التحليل في القسم ← خطة تحسين المساق : التحقق من إجراء تحليل إحصائي لنتائج الطلبة ومخرجات التعلم في نهاية كل فصل دراسي واتخاذ إجراءات لمعالجة التضخم أو التدني." },
                    { 920, "DepartmentSpecific", "faculties", "7.1.5", 189, "آلية إدارة معايرة أجهزة الفحص والقياس **", "حصر أجهزة المختبرات ← جدول الصيانة الوقائية والمعايرة الدورية ← فحص الدقة وإصدار شهادة المعايرة ← وضع ملصق حالة المعايرة: (خاص بالكليات العلمية والطبية) التحقق من صيانة ومعايرة أجهزة المختبرات العلمية والطبية لضمان دقة النتائج وسلامة التجارب." },
                    { 921, "DepartmentSpecific", "faculties", "7.1.4 / 8.5.1", 190, "السلامة العامة ومكافحة العدوى **", "أدلة السلامة المخبرية (MSDS) ← توفير معدات الوقاية والطوارئ ← بروتوكول التعقيم ومكافحة العدوى ← التخلص الآمن من النفايات الطبية/الكيميائية: (خاص بالكليات العلمية والطبية) التحقق من تطبيق إجراءات السلامة الحيوية والكيميائية ومكافحة العدوى وإدارة النفايات الخطرة في المختبرات والعيادات التعليمية." },
                    { 922, "Common", "faculties", "9.1.2", 191, "استبانات رضا الطلبة وتحليلها", "توزيع الاستبانات (تقييم المدرس والمساق، رضا الطالب العام) ← التحليل الإحصائي ← التغذية الراجعة ← خطة التحسين : التحقق من قياس رضا الطلبة وتقييمهم للمساقات والهيئة التدريسية والخدمات، وتحويل النتائج لخطط تحسين موثقة (مع معالجة الشكاوى الطلابية)." },
                    { 1001, "Common", "scientific_research", "5.3 / 7.2", 193, "الوصف الوظيفي", "توصيف المهام والصلاحيات ← الاعتماد ← التوقيع بالاستلام والعلم : التحقق من وجود بطاقات وصف وظيفي معتمدة لجميع المسميات الوظيفية في العمادة وتوقيع الموظفين عليها." },
                    { 1002, "Common", "scientific_research", "5.2 / 8.1", 194, "سياسات البحث العلمي", "الصياغة والاعتماد ← تحديد الأولويات البحثية ← النشر والتعميم للباحثين : التحقق من وجود سياسات وتعليمات واضحة ومعتمدة للبحث العلمي، دعم الأبحاث، حوافز النشر، والمشاركة في المؤتمرات، وأولويات البحث العلمي." },
                    { 1003, "DepartmentSpecific", "scientific_research", "8.5.1", 195, "دعم الباحثين", "تقديم طلب الدعم/المكافأة/المؤتمر ← تدقيق الشروط والفهرسة العالمية ← تنسيب مجلس البحث العلمي ← قرار الصرف : التحقق من فاعلية إجراءات دعم الباحثين (مكافآت النشر في المجلات المصنفة، رسوم النشر APC، دعم المشاركة في المؤتمرات العلمية)." },
                    { 1004, "DepartmentSpecific", "scientific_research", "7.1.1 / 7.1.3", 196, "الموارد", "تخصيص موازنة البحث العلمي (النسبة القانونية) ← توفير التجهيزات والبرمجيات وقواعد البيانات ← متابعة الإنفاق : التحقق من كفاية الموارد المالية والتقنية والبشرية المخصصة للبحث العلمي ومطابقتها لمعايير هيئة الاعتماد." },
                    { 1005, "DepartmentSpecific", "scientific_research", "7.5.3", 197, "ادارة البيانات البحثية", "توثيق قواعد بيانات الأبحاث والباحثين ← ضبط السجلات والنماذج ← التحقق من وجود قاعدة بيانات دقيقة ومحدثة لكافة الأبحاث المنشورة والمشاريع البحثية وبراءات الاختراع وحفظ سجلات العمادة بأمان." },
                    { 1006, "Common", "scientific_research", "7.2", 198, "التدريب والكفاءة", "حصر الاحتياج التدريبي ← خطة التدريب وورش بناء القدرات البحثية ← التنفيذ ← قياس الأثر : التحقق من تدريب كادر العمادة، وعقد ورش تدريبية لتطوير كفاءة الباحثين في النشر الدولي وكتابة المشاريع البحثية الممولة." },
                    { 1007, "Common", "scientific_research", "6.2", 199, "هدف الجودة", "صياغة أهداف ذكية ← خطة العمل ← القياس الدوري ← التحسين : التحقق من وجود أهداف جودة قابلة للقياس لعمادة البحث العلمي (مثل زيادة عدد الأبحاث المنشورة في Q1/Q2، زيادة الاستشهادات) ومتابعة تحققها." },
                    { 1008, "Common", "scientific_research", "4.1 / 6.2", 200, "الخطة الاستراتيجية", "المواءمة الاستراتيجية ← الخطة التنفيذية السنوية للبحث العلمي ← تقارير الإنجاز : التحقق من ارتباط خطة العمادة بمحور البحث العلمي والابتكار في الخطة الاستراتيجية للجامعة ومتابعة تنفيذها دوريّاً." },
                    { 1009, "Common", "scientific_research", "9.1.1", 201, "مؤشرات الأداء", "بطاقة المؤشر ← القياس الفعلي ← مقارنة المستهدف بالمتحقق ← خطة التحسين : التحقق من قياس مؤشرات أداء البحث العلمي (معدل النشر لكل عضو هيئة تدريس، معامل التأثير H-Index، نسبة الأبحاث المشتركة دوليّاً)." },
                    { 1010, "Common", "scientific_research", "4.1", 202, "تحليل SWOT", "تحليل البيئة الداخلية والخارجية ← الإقرار ← التحديث الدوري : التحقق من إجراء تحليل رباعي شامل لنقاط القوة والضعف والفرص والتهديدات الخاصة بالبحث العلمي في الجامعة." },
                    { 1011, "Common", "scientific_research", "6.1", 203, "خطة الفرص", "استخلاص الفرصة ← خطة استثمارها ← التنفيذ ومتابعة الأثر : التحقق من تحويل الفرص البحثية (المنح الدولية، المجموعات البحثية، الشراكات الصناعية) إلى مبادرات تطويرية منفذة." },
                    { 1012, "Common", "scientific_research", "6.1", 204, "إدارة المخاطر", "حصر الخطر ← تقييم (الاحتمالية x الأثر) ← خطة المعالجة ← إعادة التقييم : التحقق من تحديد مخاطر البحث العلمي (مثل النشر في مجلات مفترسة، تعثر المشاريع المدعومة، الانتحال العلمي) ووضع خطط الوقاية منها." },
                    { 1013, "DepartmentSpecific", "scientific_research", "8.5.1", 205, "تمويل الأبحاث", "الإعلان عن دورات دعم المشاريع البحثية ← التقييم والتحكيم العلمي للمقترحات ← قرار التمويل وتوقيع العقد ← التقارير المرحلية والمالية ← إغلاق المشروع والنشر : التحقق من انضباط دورة تمويل المشاريع البحثية (الداخلية والخارجية) ومتابعة إنجازها الفني والمالي حتى نشر مخرجاتها." },
                    { 1014, "DepartmentSpecific", "scientific_research", "8.5.1", 206, "أخلاقيات البحث", "ميثاق أخلاقيات البحث العلمي ← تشكيل لجنة أخلاقيات البحث (IRB) ← دراسة المقترحات البحثية وإصدار الموافقات الأخلاقية ← فحص الاستلال : التحقق من التزام الأبحاث بمعايير النزاهة الأكاديمية وأخلاقيات البحث العلمي وحقوق الملكية الفكرية." },
                    { 1015, "DepartmentSpecific", "scientific_research", "8.5.1 / 8.6", 207, "النشر العلمي", "إدارة المجلات العلمية الصادرة عن الجامعة (الاستلام، التحكيم السرّي المزدوج، التدقيق، النشر) ← توثيق النشر العلمي للجامعة : التحقق من جودة وانضباط إجراءات التحكيم والنشر في المجلات العلمية الصادرة عن الجامعة، وتوثيق النشر العلمي لأعضاء هيئة التدريس." },
                    { 1016, "Common", "scientific_research", "9.1.2", 208, "استبانات رضا اصحاب العلاقة وتحليلها", "توزيع الاستبانة على الباحثين وأعضاء هيئة التدريس ← التحليل الإحصائي ← تحديد فرص التحسين ← تنفيذ خطة التحسين : التحقق من قياس رضا الباحثين وأصحاب العلاقة عن خدمات وإجراءات عمادة البحث العلمي وتحويل النتائج لخطة تحسين." },
                    { 1101, "Common", "procurement", "", 210, "الوصف الوظيفي", "" },
                    { 1102, "Common", "procurement", "", 211, "سياسة المشتريات", "" },
